package com.example.myplayground.navigationsimport androidx.compose.runtime.Composableimport androidx.navigation.compose.NavHostimport androidx.navigation.compose.composableimport androidx.navigation.compose.rememberNavControllerimport com.example.myplayground.home.HomeScreenimport com.example.myplayground.next.NextScreen@Composablefun MockNavigation() {    val navController = rememberNavController()    NavHost(        navController = navController,        startDestination = NavigationScreens.HomeScreen.name    ) {        composable(NavigationScreens.HomeScreen.name) {             HomeScreen(navController = navController)        }        composable(NavigationScreens.NextScreen.name) {            NextScreen(navController = navController)        }    }}